def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me, last_opp = history[-1]

    total_opp_d = opp.count('D')
    total_my_d = me.count('D')

    # Pure opponent types
    if total_opp_d == 0:
        # Opponent never defected: exploit heavily near end, cooperate otherwise
        if n >= 96:
            return 'D'
        if n >= 85 and n % 3 != 0:
            return 'D'
        return 'C'
    if total_opp_d == n:
        return 'D'

    # Recent windows
    w = 8 if n >= 8 else n
    recent_opp = opp[-w:]
    recent_me = me[-w:]
    r_opp_d = recent_opp.count('D')
    r_me_d = recent_me.count('D')

    # Opponent currently very cooperative
    if r_opp_d == 0:
        # Late game exploitation
        if n >= 92:
            return 'D'
        # Occasional probing when we've been fully cooperative
        if r_me_d == 0 and n > 25 and n % 11 == 0:
            return 'D'
        return 'C'

    # Opponent currently very defective
    if r_opp_d >= w - 1:
        return 'D'

    # Estimate opponent's retaliation structure
    opp_after_my_c = 0
    opp_after_my_c_d = 0
    opp_after_my_d = 0
    opp_after_my_d_d = 0
    for i in range(n - 1):
        if me[i] == 'C':
            opp_after_my_c += 1
            if opp[i + 1] == 'D':
                opp_after_my_c_d += 1
        else:
            opp_after_my_d += 1
            if opp[i + 1] == 'D':
                opp_after_my_d_d += 1
    p_d_after_c = opp_after_my_c_d / opp_after_my_c if opp_after_my_c else 0.0
    p_d_after_d = opp_after_my_d_d / opp_after_my_d if opp_after_my_d else 0.0

    # Opponent punishes defection strongly -> keep cooperating
    if p_d_after_d >= p_d_after_c + 0.2 and n > 6:
        return 'C'
    # Opponent forgives defection -> exploit
    if p_d_after_c >= p_d_after_d + 0.3 and n > 15 and r_opp_d <= 2:
        return 'D'

    # Late game defection exploitation against moderately cooperative opponent
    if n >= 94:
        if total_opp_d * 3 <= n:
            return 'D'
        return 'D' if last_opp == 'D' else 'C'

    # Tit-for-tat with mild forgiveness and rare probing
    if last_opp == 'D':
        # Opponent defected: retaliate, but forgive if very rare overall
        if total_opp_d * 5 <= n and r_opp_d <= 1:
            return 'C'
        return 'D'

    # Opponent cooperated last round
    if total_opp_d * 4 <= n and n > 20 and n % 13 == 0:
        return 'D'
    return 'C'
